  // From year 3, situations arrive that nobody asked for. Each becomes an urgent need on this year's list:
  // it is announced at the start of the year and must be decided like every other need.
  const URGENT=[
    {key:'lift',who:'第3座高楼层住户',alert:'第3座电梯更换，停运三个月',title:'电梯停运的三个月',need:'我们住得高，电梯一停，老人和推婴儿车的都出不了门。',story:'第3座开始更换电梯，停运期间高楼层的老人、孩子和行动不便的住户每天要爬十几层楼。',primary:'comfort',secondary:'stay',balanced:['组织上下楼互助','安排邻居志愿者陪同上下楼、代买日用品。','停运期间，高楼层的老人仍能按时出门、复诊。','visits'],focused:['增设楼梯休息点','在各楼层设休息座椅并改善楼梯照明，施工期间楼道会更拥挤。','楼梯间有了休息点，上下楼不再那么难熬，楼道也因此挤了一阵。','ease']},
    {key:'dengue',who:'金文泰第2区居民',alert:'附近出现骨痛热症病例群',title:'骨痛热症病例群',need:'楼下积水一直没人清，孩子被蚊子咬得满腿包，我们很担心。',story:'国家环境局公布附近出现骨痛热症病例群，排水沟与花盆积水成了隐患，有住户已经住院。',primary:'comfort',secondary:'social',balanced:['发动邻里清积水','组织每周十分钟清理积水，挨家提醒。','邻居一起清掉了积水，病例渐渐少了。','event'],focused:['整修排水与公共绿地','疏通排水沟、改造积水绿地，施工期间部分通道要绕行。','积水点被一一改造，社区更不容易滋生蚊虫。','nrp']},
    {key:'flood',who:'底层与低洼路段住户',alert:'暴雨过后，底层和车道严重积水',title:'暴雨后的积水',need:'一下大雨，底层就淹到脚踝，老人和孩子根本过不去。',story:'一场短时暴雨让底层和低洼路段积水，送餐、上学和看病的路都被截断。',primary:'comfort',secondary:'stay',balanced:['设立雨天绕行指引','标出可走的有盖路线，安排志愿者在积水点引导。','雨天时居民知道该怎么绕行，出门不再冒险。','ramp'],focused:['改造低洼路段与排水','加高低洼路面、扩大排水口，工程期间要分段封路。','改造后的路段不再积水，雨天出门安心多了。','cover']},
    {key:'heat',who:'独居长者与轮班住户',alert:'连续数周高温，有长者中暑送医',title:'热得睡不着的夏天',need:'屋里像蒸笼，白天睡不了、晚上也睡不好，有老人已经中暑了。',story:'连续数周的高温让顶楼和西晒的单位格外闷热，独居长者和下夜班补眠的住户最难熬。',primary:'comfort',secondary:'social',balanced:['开放清凉休息点','在社区中心开放有冷气的休息角，安排邻居互相问候。','最热的日子里，长者有地方纳凉，也有人留意他们。','event'],focused:['建设遮阴与降温空间','在底层与步道加建遮阴和通风设施，施工期间会占用部分公共空间。','社区多了几处阴凉，炎热的日子里也能在楼下坐坐。','corner']},
    {key:'fire',who:'第5座受影响的住户',alert:'第5座一个单位起火，几户人家暂时无法回家',title:'火灾之后',need:'房子熏黑了，要修好几个月，我们一家暂时没地方落脚。',story:'第5座一个单位因电动车充电起火，走廊被熏黑，几户人家需要暂住别处，等待修缮。',primary:'stay',secondary:'social',balanced:['协调临时安置与互助','联络亲友和邻居提供暂住，组织捐赠日用品。','受影响的家庭有了落脚处，邻居们也伸出了援手。','visits'],focused:['设立社区援助窗口','建立一站式援助窗口，协助申请修缮与临时住房，需要长期人手。','受灾家庭的申请有人跟进，修缮和安置更快落实。','appeal']},
    {key:'layoff',who:'几户双职工家庭',alert:'附近工厂裁员，几户家庭突然失去收入',title:'突然没了收入',need:'公司说关就关，房贷、孩子的学费，下个月都不知道怎么办。',story:'附近的电子厂缩减生产线，几户双职工家庭有人失业，房贷和学费一下子成了难题。',primary:'stay',secondary:'social',balanced:['连接就业与援助资源','协助申请临时援助，介绍就业培训和职位配对。','失业的居民拿到了临时援助，也开始参加培训找新工作。','appeal'],focused:['设立就业辅导点','在社区设立长期就业辅导点，需要专人运营。','社区有了固定的就业辅导，找工作不再孤立无援。','appeal']},
    {key:'hawker',who:'常去食阁的老街坊',alert:'食阁闭馆翻新一年，老街坊没了聚脚处',title:'食阁关门的一年',need:'食阁一关，早上不知道去哪里喝咖啡，老朋友也很难见到了。',story:'食阁闭馆翻新一年，许多老人失去了每天见面的地方，附近的摊贩也暂时搬走。',primary:'social',secondary:'comfort',balanced:['安排临时聚脚点','在底层设临时茶座，组织每周的老友聚会。','食阁翻新期间，老朋友们仍有地方见面聊天。','event'],focused:['建设社区茶座空间','把一处底层空间改造成固定的社区茶座，占用部分公共空间。','社区多了一个固定的聚脚处，食阁重开后也一样热闹。','corner']},
    {key:'fall',who:'独居长者',alert:'一位独居长者跌倒两天后才被发现',title:'没人知道她跌倒了',need:'一个人住，最怕的就是跌倒了没人知道。',story:'一位独居长者在家跌倒，两天后才被邻居发现，楼里的独居长者人心惶惶。',primary:'stay',secondary:'comfort',balanced:['建立邻里互相问候','组织邻居每天打个招呼、留意信箱和灯光。','独居的长者每天都有人问候，出了事也能很快被发现。','visits'],focused:['扩建乐龄关怀服务','扩建乐龄活动中心，增加定期探访与紧急求助联络，需要长期人手。','乐龄关怀扩大后，独居长者有了固定联系的人。','aac']},
    {key:'bus',who:'有学龄孩子的家庭',alert:'校车公司停运，孩子们上学没了着落',title:'校车停了以后',need:'校车说停就停，我们上班赶不及，孩子每天怎么去学校？',story:'负责附近几所学校的校车公司突然停运，双职工家庭每天早上手忙脚乱。',primary:'comfort',secondary:'social',balanced:['组织家长轮流接送','协调家长轮班接送，让孩子结伴步行上学。','家长们轮流接送，孩子们结伴上学也更有伴。','event'],focused:['建设课后集合点','在社区设立课后与接送集合点，需要专人管理。','孩子放学有了安全的去处，家长下班也能安心接回。','child']},
    {key:'noise',who:'同一层的邻居们',alert:'多户同时装修，噪音和粉尘引发争吵',title:'装修季的争吵',need:'天天电钻声，上夜班的人睡不了，孩子也没法做功课。',story:'几户人家同时进行翻新，噪音、粉尘和走廊堆放的建材让邻里关系越来越紧张。',primary:'social',secondary:'comfort',balanced:['调解施工时间','约齐装修户和邻居，商定安静时段与清洁安排。','装修户和邻居有了共同的约定，争吵少了。','action-mediate'],focused:['改善走廊与公共空间','翻新走廊、增设收纳与隔音设施，施工期间会暂时更吵。','走廊变整洁了，以后再有装修也不那么扰人。','nrp']},
    {key:'scam',who:'年长住户',alert:'多名年长住户接到诈骗电话，有人被骗走积蓄',title:'电话那头的骗局',need:'那人说是银行打来的，我差点把养老钱都转出去了。',story:'冒充银行和政府官员的诈骗电话接连打给年长住户，已经有人被骗走积蓄，大家既害怕又羞于开口。',primary:'social',secondary:'stay',balanced:['举办防诈骗分享会','在底层举办防诈骗分享，教长者辨认可疑电话。','长者学会了辨认骗局，遇到可疑电话会先找人商量。','event'],focused:['设立社区咨询窗口','设立可以随时求助、核实信息的咨询窗口，需要专人值守。','长者有了可以信任的求助窗口，被骗的人也少了。','appeal']},
    {key:'haze',who:'有长者和幼儿的家庭',alert:'烟霾笼罩数周，空气质量持续不健康',title:'烟霾季节',need:'窗都不敢开，老人咳个不停，孩子也不能出去玩。',story:'区域烟霾笼罩数周，空气质量指数持续在不健康水平，长者和幼儿出现呼吸不适。',primary:'comfort',secondary:'stay',balanced:['分发口罩并开放净化室','向长者和幼儿家庭分发口罩，开放有空气净化的活动室。','烟霾期间，最脆弱的居民有了避开烟霾的地方。','visits'],focused:['改善公共室内空气','为社区中心加装空气净化与通风设备，需要长期维护。','社区中心成了烟霾天也能安心待着的地方。','ease']}
  ].map(c=>({...c,urgent:true,residentId:'urgent-'+c.key,question:'这件事最需要先解决什么？'}));
  const URGENT_FROM=3,URGENT_SECOND=[6];
  // A fixed order per save: no situation repeats across the seven years.
  function urgentKeys(s,year){if(!s||year<URGENT_FROM)return [];const next=random(((s.seed>>>0)^0x9e3779b9)>>>0),order=URGENT.map(c=>c.key);for(let i=order.length-1;i>0;i--){const j=Math.floor(next()*(i+1));[order[i],order[j]]=[order[j],order[i]];}
    let n=0;for(let y=URGENT_FROM;y<year;y++)n+=1+(URGENT_SECOND.includes(y)?1:0);return order.slice(n,n+1+(URGENT_SECOND.includes(year)?1:0));}
  function urgentCases(year,s){return urgentKeys(s,year).map(k=>buildCase(year,s,URGENT.find(c=>c.key===k),'y'+year+'-urgent-'+k));}
  function urgent(s){return valid(s)?copy(urgentCases(s.year,s)):[];}
  function urgentInfo(id){const key=String(id||'').replace(/^urgent-/,''),c=URGENT.find(x=>x.key===key);return c?copy({key:c.key,residentId:c.residentId,who:c.who,alert:c.alert,title:c.title}):null;}
  function catalogue(year,s){const annual=YEARS[year-1];const cases=PEOPLE.map(h=>{const current=annual.cases.find(c=>c.residentId===h.id);if(current)return current;const base=YEARS.flatMap(y=>y.cases).find(c=>c.residentId===h.id);return {...base,key:'visit-'+h.id,title:'近况中的需要',need:('lin students kumar rahman'.split(' ').includes(h.id)?'我们':'我')+OPTIONAL_NOTES[h.id],story:'本年入户交流。'+OPTIONAL_NOTES[h.id],question:'日常里最希望社区帮忙改善什么？'};});const defaults=cases.map(c=>buildCase(year,s,c,'y'+year+'-'+c.key));const found=s?.discoveredNeeds?.['y'+year]||[];return defaults.filter(i=>!found.some(d=>d.residentId===i.residentId)).concat(copy(found).map(i=>policyText(year,i)));}
  function recordNeeds(s,residentId,needs){if(!inConversation(s))return fail('当前不能记录需求');if(!canVisit(s,residentId))return fail('这户今年不方便接待探访。');const base=catalogue(s.year,s).find(i=>i.residentId===residentId);if(!base)return fail('未知住户');if(rawIssues(s.year,s).some(i=>i.residentId===residentId))return {ok:true,already:true};if(!Array.isArray(needs)||!needs.some(n=>n&&typeof n.title==='string'&&typeof n.detail==='string'&&n.detail.trim()))return {ok:true};s.discoveredNeeds=s.discoveredNeeds||{};const key='y'+s.year;const entries=s.discoveredNeeds[key]||(s.discoveredNeeds[key]=[]);entries.push(copy(base));s.learnedIssues[base.id]=true;return {ok:true};}
  function rawIssues(year,s){return catalogue(year,s).filter(i=>s?.learnedIssues?.[i.id]===true||s?.selected?.[i.id]).concat(urgentCases(year,s));}
  function households(){return copy(PEOPLE);}
  function issues(s){return valid(s)?copy(rawIssues(s.year,s)):[];}
  function additionalVisits(s){return inConversation(s)?copy(catalogue(s.year,s).filter(i=>!s.learnedIssues?.[i.id])):[];}
  function visitIssue(s,id){return valid(s)?copy(catalogue(s.year,s).find(i=>i.id===id)||null):null;}
  function learned(s,id){return !!s?.learnedIssues?.[id]||/-urgent-/.test(String(id||''))&&urgentCases(s?.year,s).some(i=>i.id===id);}
  function learn(s,id){if(!inConversation(s))return fail('当前不能探访。');const issue=visitIssue(s,id);if(!issue)return fail('未找到住户需求。');if(!canVisit(s,issue.residentId))return fail('这户今年不方便接待探访。');if(s.learnedIssues[id])return {ok:true,already:true};s.learnedIssues[id]=true;log(s,'探访'+name(issue.residentId)+'：'+issue.title);return {ok:true,message:'需求已记录。'};}
  function summarize(s){if(!valid(s)||s.phase!=='visit'||s.outcome)return fail('现在不能整理年度需求。');s.phase='needs';return {ok:true,message:'已整理实际探访中了解的需求。'};}
  function beginPolicies(s){if(!valid(s)||s.phase!=='needs'||s.outcome)return fail('先查看本年的需求报告。');s.phase='policy';return {ok:true,message:'为每项需求各选一项政策。'};}
  function choices(s){if(!valid(s))return [];return rawIssues(s.year,s).flatMap(i=>{const p=i.policies.find(p=>p.id===s.selected?.[i.id]);return p?[copy({issueId:i.id,residentId:i.residentId,policyId:p.id,...p})]:[];});}
  function reservation(s,list){const seen=new Set(Object.keys(s.assets||{}));let newOngoing=0;for(const p of list)if(p.assetId&&!seen.has(p.assetId)){seen.add(p.assetId);newOngoing++;}const temporary=list.reduce((n,p)=>n+p.staff,0),committed=ongoing(s)+temporary+newOngoing;return {cost:list.reduce((n,p)=>n+p.cost,0),staff:temporary,newOngoingStaff:newOngoing,ongoing:ongoing(s),staffCommitted:committed,remainingStaff:s.staffTotal-committed,remainingCash:s.cash-list.reduce((n,p)=>n+p.cost,0)};}
  function prospectiveChoices(s,selected){return rawIssues(s.year,s).flatMap(i=>{const p=i.policies.find(p=>p.id===selected[i.id]);return p?[{issueId:i.id,residentId:i.residentId,policyId:p.id,...p}]:[];});}
  function canChoose(s,id,policyId){if(!valid(s)||s.phase!=='policy'||s.outcome)return fail('先查看需求报告，再选择政策。');const list=rawIssues(s.year,s),issue=list.find(i=>i.id===id),policy=issue?.policies.find(p=>p.id===policyId);if(!policy)return fail('没有找到本年的这项政策。');const next={...s.selected,[id]:policyId},reserved=reservation(s,prospectiveChoices(s,next));if(reserved.remainingCash<0)return fail('财政还差'+(-reserved.remainingCash)+'。可选择资金较少的基础协调方案。');if(reserved.remainingStaff<0)return fail('可用人力还差'+(-reserved.remainingStaff)+'。公共投入还需为新部门预留1个长期运营岗；可换成委托服务或调整另一项政策。');const missing=list.filter(i=>!next[i.id]);const minimum=missing.reduce((n,i)=>n+Math.min(...i.policies.map(p=>p.cost)),0);if(reserved.remainingCash<minimum)return fail('请为其余需求保留基础协调资金。');return {ok:true,message:'资金与人力足够，本年结算前可以更改。',...reserved};}
  function choose(s,id,policyId){const result=canChoose(s,id,policyId);if(!result.ok)return result;s.selected={...s.selected,[id]:policyId};compatibility(s);return {ok:true,message:'政策已预留资金与人力，尚未结算。'};}
  function metricPreview(s,list){const before=copy(s.metrics),yearly=natural(),raw={...yearly};list.forEach(p=>AXES.forEach(k=>{raw[k]+=p.effects[k];}));const after={},changes={};AXES.forEach(k=>{after[k]=clamp(before[k]+raw[k]);changes[k]=after[k]-before[k];});return {before,after,changes,natural:yearly,rawChanges:raw,capped:AXES.some(k=>before[k]+raw[k]!==after[k])};}
